// Normalize Analytics Data
//
// Input : one item = the raw Athena GetQueryResults response.
// Output: one item per brand = that brand's analytics rows grouped by level,
//         in Athena's own order.
//
// This node does NOT calculate anything. Athena is the source of truth for
// period generation, aggregation, metric calculation, brand split and ordering.

const SUPPORTED_LEVELS = ['year', 'month', 'week', 'day', '3h'];

const NUMERIC_COLUMNS = [
  'ftd',
  'std',
  'total_dep',
  'in_out',
  'ggr',
  'ngr',
  'margin_pct',
  'hold',
  'reg2dep',
  'ftd2std',
  'ar_psp',
  'ar_psp_deposits',
];

/** Athena returns every value as a string, or omits VarCharValue entirely for NULL. */
function cellValue(cell) {
  if (cell === null || cell === undefined) return null;
  const raw = cell.VarCharValue;
  if (raw === null || raw === undefined) return null;
  return String(raw);
}

/** Numbers arrive as strings. Anything unparseable becomes null, never NaN. */
function toNumber(raw) {
  if (raw === null || raw === undefined) return null;
  const trimmed = String(raw).trim();
  if (trimmed === '') return null;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : null;
}

function emptyLevels() {
  return { year: [], month: [], week: [], day: [], '3h': [] };
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(
    `Normalize Analytics Data expected exactly 1 input item from Athena, received ${inputItems.length}.`,
  );
}

const response = inputItems[0].json ?? {};

if (response.NextToken) {
  throw new Error(
    'Athena returned a paginated result (NextToken present). This workflow reads a single ' +
      'page of up to 1000 rows and does not implement pagination. The analytics query is not ' +
      'expected to exceed that; if it now does, add pagination before trusting this report.',
  );
}

const resultSet = response.ResultSet;
if (!resultSet || !Array.isArray(resultSet.Rows)) {
  throw new Error(
    'Unexpected Athena response: ResultSet.Rows is missing. Check the Get Athena Results node output.',
  );
}

const columns = (resultSet.ResultSetMetadata?.ColumnInfo ?? []).map((column) => column?.Name);
if (columns.length === 0) {
  throw new Error('Unexpected Athena response: ResultSetMetadata.ColumnInfo is empty.');
}

if (!columns.includes('brand')) {
  throw new Error(
    'Athena result has no `brand` column. This report splits one Slack message per brand, ' +
      'so the query must select it. The analytics SQL and this node have drifted apart — ' +
      'update both together.',
  );
}

// Athena prepends a header row whose values are the column names. It is metadata, not data.
let rows = resultSet.Rows;
const firstRowValues = (rows[0]?.Data ?? []).map(cellValue);
const firstRowIsHeader =
  firstRowValues.length === columns.length &&
  firstRowValues.every((value, index) => value === columns[index]);
if (firstRowIsHeader) {
  rows = rows.slice(1);
}

// Insertion order is Athena's order, which the query fixes with ORDER BY brand, sort_order.
const brands = new Map();
const unknownLevels = new Set();
let rowCount = 0;

for (const row of rows) {
  const cells = row?.Data ?? [];

  const record = {};
  columns.forEach((columnName, index) => {
    record[columnName] = cellValue(cells[index]);
  });

  // Skip rows that carry no values at all rather than emitting a row of dashes.
  if (Object.values(record).every((value) => value === null)) continue;

  const level = record.level === null ? null : record.level.trim();
  if (!level || !SUPPORTED_LEVELS.includes(level)) {
    unknownLevels.add(String(record.level));
    continue;
  }

  const brand = record.brand === null ? '' : record.brand.trim();
  if (brand === '') {
    throw new Error(
      `Athena returned a row with an empty brand (level "${level}", period "${record.period}"). ` +
        'Every row must belong to a brand, since each brand becomes its own Slack message.',
    );
  }

  const normalized = {
    level,
    period: record.period === null ? null : record.period.trim(),
  };
  for (const column of NUMERIC_COLUMNS) {
    normalized[column] = toNumber(record[column]);
  }

  if (!brands.has(brand)) brands.set(brand, emptyLevels());
  brands.get(brand)[level].push(normalized);
  rowCount += 1;
}

if (unknownLevels.size > 0) {
  throw new Error(
    `Athena returned unsupported level value(s): ${[...unknownLevels].join(', ')}. ` +
      `Supported levels are ${SUPPORTED_LEVELS.join(', ')}. ` +
      'The analytics SQL and this node have drifted apart — update both together.',
  );
}

if (rowCount === 0) {
  throw new Error(
    'Athena query succeeded but returned zero analytics rows. No Slack report was sent. ' +
      'Check that the source tables have data for the current periods.',
  );
}

// One item per brand. Everything downstream — payload and Slack request — runs once per item.
return [...brands.entries()].map(([brand, levels]) => ({ json: { brand, levels } }));

// Build Slack Payload
//
// Input : one item per brand = that brand's rows grouped by level (from Normalize Analytics Data).
// Output: one item per brand = the complete Slack Incoming Webhook payload for that brand.
//
// This node only presents data: Block Kit structure, labels, number formatting and the
// Europe/Kyiv report timestamp. It never recalculates a metric.
//
// Layout, per brand: one message carrying two Block Kit `table` blocks — Volume and
// Conversion. Both use the same rows (one per period across every level), so a period
// lines up across the two tables. Twelve metrics do not fit Slack's 10-column table
// limit in a single table, which is why the split exists.

const REPORT_TIMEZONE = 'Europe/Kyiv';
const MISSING = '—';

// Slack's own limits for a table block.
const SLACK_MAX_TABLE_ROWS = 100;
const SLACK_MAX_TABLE_COLUMNS = 10;

// One table per entry. Column order after the leading "Period" column is the field order here.
const TABLES = [
  {
    title: 'Volume',
    fields: [
      { key: 'ftd', label: 'FTD', format: 'integer' },
      { key: 'std', label: 'STD', format: 'integer' },
      { key: 'total_dep', label: 'Total Dep', format: 'integer' },
      { key: 'in_out', label: 'In-Out', format: 'integer' },
      { key: 'ggr', label: 'GGR', format: 'integer' },
      { key: 'ngr', label: 'NGR', format: 'integer' },
      { key: 'margin_pct', label: 'Margin', format: 'percent' },
    ],
  },
  {
    title: 'Conversion',
    fields: [
      { key: 'hold', label: 'Hold', format: 'percent' },
      { key: 'reg2dep', label: 'Reg2Dep', format: 'percent' },
      { key: 'ftd2std', label: 'Ftd2Std', format: 'percent' },
      { key: 'ar_psp', label: 'AR PSP', format: 'percent' },
      { key: 'ar_psp_deposits', label: 'AR PSP Deposits', format: 'percent' },
    ],
  },
];

// Row order inside each table. `label` prefixes each period cell, e.g. "MONTH · August 2026".
const GROUPS = [
  { key: 'year', label: 'YEAR' },
  { key: 'month', label: 'MONTH' },
  { key: 'week', label: 'WEEK' },
  { key: 'day', label: 'DAY' },
  { key: '3h', label: '3H' },
];

function toFiniteNumber(value) {
  if (value === null || value === undefined) return null;
  const parsed = typeof value === 'number' ? value : Number(String(value).trim());
  return Number.isFinite(parsed) ? parsed : null;
}

function formatInteger(value) {
  const parsed = toFiniteNumber(value);
  if (parsed === null) return MISSING;
  return Math.round(parsed).toLocaleString('en-US');
}

function formatPercent(value) {
  const parsed = toFiniteNumber(value);
  if (parsed === null) return MISSING;
  return `${parsed.toFixed(1)}%`;
}

function formatMetric(row, field) {
  return field.format === 'integer' ? formatInteger(row[field.key]) : formatPercent(row[field.key]);
}

/** Table cells are raw_text: Slack renders them verbatim, so no mrkdwn escaping. */
function cell(text) {
  return { type: 'raw_text', text: String(text) };
}

function formatInTimezone(date, options) {
  return new Intl.DateTimeFormat(options.locale ?? 'en-GB', {
    timeZone: REPORT_TIMEZONE,
    ...options.parts,
  }).format(date);
}

for (const table of TABLES) {
  const columnCount = table.fields.length + 1;
  if (columnCount > SLACK_MAX_TABLE_COLUMNS) {
    throw new Error(
      `The "${table.title}" table needs ${columnCount} columns, above Slack's limit of ` +
        `${SLACK_MAX_TABLE_COLUMNS}. Remove a metric from it or split it further.`,
    );
  }
}

const inputItems = $input.all();
if (inputItems.length === 0) {
  throw new Error('Build Slack Payload received no brands to report. No Slack report was sent.');
}

const now = new Date();
const reportDate = formatInTimezone(now, {
  parts: { day: '2-digit', month: 'short', year: 'numeric' },
});
const reportTime = formatInTimezone(now, {
  parts: { hour: '2-digit', minute: '2-digit', hour12: false },
});

/** The ordered period list a brand contributes, shared by both of its tables. */
function periodLabels(levels) {
  const labels = [];
  for (const group of GROUPS) {
    const groupRows = Array.isArray(levels[group.key]) ? levels[group.key] : [];
    // A level with no rows contributes no table rows rather than a row of dashes.
    for (const row of groupRows) {
      const period =
        typeof row.period === 'string' && row.period.trim() !== '' ? row.period.trim() : MISSING;
      labels.push({ label: `${group.label} · ${period}`, row });
    }
  }
  return labels;
}

function tableBlock(table, periods, brand) {
  const rows = [[cell('Period'), ...table.fields.map((field) => cell(field.label))]];
  for (const { label, row } of periods) {
    rows.push([cell(label), ...table.fields.map((field) => cell(formatMetric(row, field)))]);
  }

  if (rows.length > SLACK_MAX_TABLE_ROWS) {
    throw new Error(
      `The "${table.title}" table for ${brand} has ${rows.length} rows, above Slack's limit of ` +
        `${SLACK_MAX_TABLE_ROWS}. Athena returned more periods than this report layout allows.`,
    );
  }

  return {
    type: 'table',
    // Period label left-aligned, every metric right-aligned so digits line up.
    column_settings: [{ align: 'left' }, ...table.fields.map(() => ({ align: 'right' }))],
    rows,
  };
}

return inputItems.map((item) => {
  const brandData = item.json ?? {};
  const brand =
    typeof brandData.brand === 'string' && brandData.brand.trim() !== ''
      ? brandData.brand.trim()
      : null;
  if (!brand) {
    throw new Error('Build Slack Payload received an item without a brand. No Slack report was sent.');
  }

  const periods = periodLabels(brandData.levels ?? {});
  if (periods.length === 0) {
    throw new Error(
      `No analytics periods to report for ${brand} — every level was empty after normalization. ` +
        'No Slack report was sent.',
    );
  }

  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `📊 Analytics Report — ${brand}` } },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `${reportDate} • ${REPORT_TIMEZONE} • Updated ${reportTime}`,
        },
      ],
    },
  ];

  for (const table of TABLES) {
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${table.title}*` } });
    blocks.push(tableBlock(table, periods, brand));
  }

  return {
    json: {
      brand,
      text: `Analytics Report ${brand} — ${reportDate} • ${REPORT_TIMEZONE} • Updated ${reportTime}`,
      blocks,
    },
  };
});
